<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoVariableFinanciera, guardarVariableFinanciera, listarVariablesFinancieras, obtenerSiguienteCodigo } from '../services/variablesFinancieras'
import type { TipoPeriodoFinanciero, TipoPublicacionFinanciera, TipoValorFinanciero, VariableFinanciera, VariableFinancieraPayload } from '../interfaces/variablesFinancieras.interface'

const rows=ref<VariableFinanciera[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive<VariableFinancieraPayload>({codigo:'',nombre:'',formula_valor:'',tipo_periodo:'M',tipo_valor:'Contable',cod_equivalente:null,tipo_equivalente:null,unidad_ambito:null})
const periodos:{value:TipoPeriodoFinanciero;label:string}[]=[{value:'M',label:'Mensual'},{value:'A',label:'Acumulada'}]
const valores:TipoValorFinanciero[]=['Contable','Predeterminado','Fijo','Formula']
const publicaciones:TipoPublicacionFinanciera[]=['LOCAL','SUNASS/OTASS','SUNASS','OTASS']
const message=(value:unknown)=>value instanceof Error?value.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const response=await listarVariablesFinancieras(criterio.value,next);rows.value=response.data;page.value=response.current_page;lastPage.value=response.last_page;total.value=response.total}catch(value){error.value=message(value)}finally{loading.value=false}}
async function open(item?:VariableFinanciera){editing.value=item?.id??null;form.codigo=item?.codigo??'';form.nombre=item?.nombre??'';form.formula_valor=item?.formula_valor??'';form.tipo_periodo=item?.tipo_periodo??'M';form.tipo_valor=item?.tipo_valor??'Contable';form.cod_equivalente=item?.cod_equivalente??null;form.tipo_equivalente=item?.tipo_equivalente??null;form.unidad_ambito=item?.unidad_ambito??null;error.value='';modal.value=true;if(!item)try{form.codigo=(await obtenerSiguienteCodigo()).codigo}catch(value){modal.value=false;error.value=message(value)}}
async function save(){const nombre=form.nombre.trim(),formula=form.formula_valor.trim();if(!form.codigo?.trim())return void(error.value='No se pudo obtener el código de la variable.');if(nombre.length<2||nombre.length>100)return void(error.value='El nombre debe tener entre 2 y 100 caracteres.');if(!formula||formula.length>200)return void(error.value='La fórmula o valor es obligatorio y admite hasta 200 caracteres.');saving.value=true;try{await guardarVariableFinanciera(editing.value,{...form,codigo:form.codigo.toUpperCase(),nombre:nombre.toUpperCase(),formula_valor:formula,cod_equivalente:form.cod_equivalente?.trim()||null,tipo_equivalente:form.tipo_equivalente||null,unidad_ambito:form.unidad_ambito?.trim()||null});modal.value=false;success.value=`Variable ${editing.value?'actualizada':'registrada'} correctamente.`;await load(editing.value?page.value:1)}catch(value){error.value=message(value)}finally{saving.value=false}}
async function toggle(item:VariableFinanciera){if(!confirm(`¿Desea ${item.estado?'desactivar':'activar'} la variable ${item.codigo}?`))return;try{await cambiarEstadoVariableFinanciera(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(value){error.value=message(value)}}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / Variables financieras</nav><header class="hero"><div class="mark">VF</div><div><small>MIA · CONTABILIDAD · MAESTROS</small><h1>Variables financieras</h1><p>Define fórmulas y valores utilizados para calcular indicadores financieros.</p></div><strong>{{total}} variables</strong><button @click="open()">+ Nueva variable</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="criterio" placeholder="Buscar por código o nombre"><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form><section class="table-card"><div v-if="loading" class="empty">Consultando variables…</div><div v-else-if="!rows.length" class="empty">No se encontraron variables financieras.</div><div v-else class="scroll"><table><thead><tr><th>Código</th><th>Nombre</th><th>Fórmula / valor</th><th>Periodo</th><th>Tipo valor</th><th>Cód. equiv.</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.codigo}}</b></td><td>{{item.nombre}}</td><td><code>{{item.formula_valor}}</code></td><td><span class="period">{{item.tipo_periodo_label||(item.tipo_periodo==='M'?'Mensual':'Acumulada')}}</span></td><td>{{item.tipo_valor_label||item.tipo_valor}}</td><td>{{item.cod_equivalente||'—'}}</td><td><span :class="item.estado?'ok':'bad'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button class="soft" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>VARIABLE FINANCIERA</small><h2>{{editing?'Editar':'Nueva'}} variable</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="5" readonly></label><label class="wide">Nombre / detalle *<input v-model="form.nombre" minlength="2" maxlength="100" @input="form.nombre=form.nombre.toUpperCase()"></label><label class="wide">Fórmula / valor fijo *<input v-model="form.formula_valor" maxlength="200"><small>Ej.: 339, 10+12+14, PO0018(SUCURSAL,FECHA,TIPO)</small></label><label>Tipo período *<select v-model="form.tipo_periodo"><option v-for="option in periodos" :key="option.value" :value="option.value">{{option.label}}</option></select></label><label>Tipo valor *<select v-model="form.tipo_valor"><option v-for="option in valores" :key="option" :value="option">{{option}}</option></select></label><label>Código equivalente<input v-model="form.cod_equivalente" maxlength="10"></label><label>Publicación<select v-model="form.tipo_equivalente"><option :value="null">Sin publicación</option><option v-for="option in publicaciones" :key="option" :value="option">{{option}}</option></select></label><label>Unidad / ámbito<input v-model="form.unidad_ambito" maxlength="10" placeholder="S/., USD, %"></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">Guardar</button></footer></form></div></div></template>

<style scoped>
.page{--accent:#385d8a;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.dialog>header small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;color:var(--accent);font-size:.55rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;font-size:.6rem}.success{color:#287052;background:#edf9f3}.error{color:#a64046;background:#fff0f0}.filters{margin-top:10px;padding:13px;display:flex;gap:7px;border-radius:9px;background:#fff}.filters input,.dialog input,.dialog select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.55rem}.filters input{margin-right:auto}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.scroll{overflow:auto}table{width:100%;min-width:1050px;border-collapse:collapse;font-size:.53rem}th,td{padding:10px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#4c627e}code{font-size:.5rem}.ok,.bad,.period{padding:4px 7px;border-radius:10px;font-size:.43rem}.ok{color:#287154;background:#e6f7ee}.bad{color:#9d4046;background:#fdebed}.period{color:#385d8a;background:#e8eff8}.actions{display:flex;gap:4px}.actions button{padding:6px 7px;border:0;border-radius:5px;font-size:.45rem}.edit{color:#385d8a;background:#e8eff8}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(760px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;justify-content:space-between}.dialog h2{margin:3px 0 15px;font-size:.9rem}.dialog>header button{color:#59666c;background:none;font-size:1.1rem}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.dialog label{display:grid;font-size:.52rem}.dialog input,.dialog select{margin-top:5px}.dialog label small{margin-top:4px;color:#89959b;font-size:.44rem}.wide{grid-column:span 2}.dialog footer{margin-top:17px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:720px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters input{flex-basis:100%}.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style>
